#!/usr/bin/env python3
"""AKE Master Launcher — single-cell Colab entry point for the AKE Server Adapter.

WHAT THIS IS
    Paste this whole file into one Colab cell and press Shift+Enter. It uploads and wires
    up everything needed to run AKE's web dashboard behind a public Cloudflare URL, while
    leaving the existing interactive AKE terminal exactly as it was.

WHAT IT DOES, IN ORDER
    1. Prompts you to upload AKE_Runtime.zip and ake_server.zip (a workbook .xlsx is
       optional — skip it and the bundled EBIS workbook is used automatically).
    2. Extracts both zips into one working directory, laid out the way ake_server/adapter.py
       already expects: AKE_MASTER.py, ake/, and ake_server/ as siblings.
    3. Installs ake_server's dependencies (fastapi/uvicorn/etc.) and starts it.
    4. Starts a Cloudflare quick tunnel pointed at that server and prints the public
       dashboard URL — the ONLY thing printed about the tunnel is that URL. It is never
       written into the dashboard itself or exposed through any API route; the only place
       it appears is this Colab output, which only you (running this cell) see.
    5. Boots the SAME interactive AKE terminal AKE_Colab_Shell.py already provides —
       identical call, identical behavior, running live in this same cell.

WHAT THIS DOES NOT TOUCH
    Nothing under ake/, and no line of AKE_MASTER.py, AKE_SHELL.py, AKE_Colab_Shell.py,
    colab_run.py, demo.py, or ake_server/ is modified. The one new file this script writes
    outside the working directory's own extracted content, ake_server_gateway.py, is a
    sibling of ake_server/ that only IMPORTS ake_server.api's already-built `app` object to
    mount static files onto it — the same "reuse via import, never edit" pattern
    ake_server/adapter.py itself already uses for AKE_MASTER.locate_workbook.

IF A FRONTEND IS ALREADY INSIDE ake_server.zip
    ake_server_gateway.py looks for one first (ake_server/static|frontend|dashboard|public/
    index.html) and serves that instead — the bundled dashboard below is only ever a
    fallback for when none exists yet.

OUTSIDE COLAB
    If google.colab isn't importable, this looks for AKE_Runtime.zip / ake_server.zip /
    *.xlsx already sitting next to this script instead of prompting an upload dialog,
    mirroring AKE_Colab_Shell.py's own fallback — so `python AKE_Master_Launcher.py` also
    works for local testing.

ADMIN SETTINGS
    Edit the constants right below before running the cell if you need something other
    than the defaults.
"""
import base64
import glob
import io
import json
import os
import re
import shutil
import signal
import subprocess
import sys
import threading
import time
import zipfile

# ============================================================================
# Admin settings — edit these before running the cell if needed
# ============================================================================

# "owner"     -> everyone who opens the dashboard shares the one workbook loaded below
#                (the uploaded one, or the bundled EBIS workbook if you skipped upload).
# "workspace" -> the dashboard shows an upload screen instead; each visitor's session gets
#                its own private workbook and its own in-memory runtime.
#
# None = ASK at launch (recommended). The runtime, not the browser and not a constant in
# this file, is the source of truth for mode — so it must be chosen where you can see it.
# Set it to "owner" or "workspace" here only if you want to skip the prompt entirely.
SERVER_MODE = None

SERVER_PORT = 8000          # local port ake_server + dashboard listen on; tunnelled publicly
STARTUP_TIMEOUT = 60        # seconds to wait for the server to answer /health
TUNNEL_TIMEOUT = 45         # seconds to wait for cloudflared to hand back a public URL
TUNNEL_DNS_TIMEOUT = 75     # seconds to wait for that URL's edge DNS to actually resolve
                            # (this is what prevents printing a URL that returns NXDOMAIN)
TUNNEL_ATTEMPTS = 3         # if a tunnel registers but never becomes reachable, retry with
                            # a fresh subdomain this many times before giving up
WORKING_DIR = None          # None = auto (Colab: /content/ake_runtime_live, else ./ake_runtime_live)

