_PIDFILE_NAME = ".ake_launcher_pids.json"


# ============================================================================
# Environment detection
# ============================================================================

def _in_colab():
    try:
        import google.colab  # noqa: F401
        return True
    except ImportError:
        return False


def _default_working_dir():
    base = "/content" if _in_colab() else os.getcwd()
    return os.path.join(base, "ake_runtime_live")


# ============================================================================
# Step 1 — uploads
# ============================================================================

def _collect_uploads():
    """Return {filename: bytes} for AKE_Runtime.zip / ake_server.zip / an optional
    workbook. In Colab this opens ONE upload dialog — the browser's own file picker
    supports selecting all three at once. Outside Colab it looks for the same three
    things already on disk, mirroring AKE_Colab_Shell.py's own _get_uploads() fallback."""
    if _in_colab():
        from google.colab import files
        print("Select AKE_Runtime.zip and ake_server.zip together (multi-select works in "
              "the dialog). Add your workbook .xlsx too if you have one — otherwise the "
              "bundled EBIS workbook is used automatically.")
        try:
            uploaded = files.upload()
        except KeyboardInterrupt:
            sys.exit("\nUpload cancelled. Re-run this cell to try again.")
        return dict(uploaded)
    found = {}
    for pat in ("AKE_Runtime.zip", "ake_server.zip", "*.xlsx"):
        for f in glob.glob(pat):
            if f not in found and "~$" not in f:
                with open(f, "rb") as fh:
                    found[f] = fh.read()
    return found


def _classify_uploads(uploads):
    """Sort uploaded files into (runtime_zip_bytes, server_zip_bytes, workbook_bytes,
    workbook_name) by peeking at zip contents, not just filename — a renamed file still
    resolves correctly. Mirrors the tolerant-detection style locate_workbook() and
    AKE_Colab_Shell._extract_runtime() already use."""
    runtime_zip = server_zip = workbook_bytes = None
    workbook_name = None
    for name, data in uploads.items():
        low = name.lower()
        if low.endswith(".xlsx") and "~$" not in low:
            workbook_bytes, workbook_name = data, name
            continue
        if not low.endswith(".zip"):
            continue
        try:
            with zipfile.ZipFile(io.BytesIO(data)) as z:
                names = z.namelist()
        except zipfile.BadZipFile:
            continue
        has_ake_pkg = any(n.rstrip("/").endswith("/ake") or n.rstrip("/") == "ake" for n in names)
        has_master = any(n.endswith("AKE_MASTER.py") for n in names)
        has_server_pkg = any(
            n.endswith("ake_server/adapter.py") or n.endswith("ake_server/api.py") for n in names
        )
        if has_server_pkg and not (has_ake_pkg or has_master):
            server_zip = data
        elif has_ake_pkg or has_master:
            runtime_zip = data
        elif "server" in low:
            server_zip = server_zip or data
        else:
            runtime_zip = runtime_zip or data
    return runtime_zip, server_zip, workbook_bytes, workbook_name


# ============================================================================
# Step 2 — extraction, laid out the way ake_server/adapter.py expects:
#   root/AKE_MASTER.py, root/ake/, root/ake_server/  (all siblings)
# ============================================================================

def _extract_runtime_zip(data, dest_root):
    """Extract AKE_Runtime.zip-style bytes so dest_root directly contains ake/ and
    AKE_MASTER.py, tolerant of the shipped 'AKE_Runtime/' wrapper folder or a flat zip —
    same tolerance AKE_Colab_Shell.py::_extract_runtime already relies on."""
    tmp = _mkdtemp("ake_runtime_src_")
    with zipfile.ZipFile(io.BytesIO(data)) as z:
        z.extractall(tmp)
    src = tmp
    if not os.path.isdir(os.path.join(tmp, "ake")):
        for name in os.listdir(tmp):
            sub = os.path.join(tmp, name)
            if os.path.isdir(sub) and os.path.isdir(os.path.join(sub, "ake")):
                src = sub
                break
    os.makedirs(dest_root, exist_ok=True)
    for item in os.listdir(src):
        s, d = os.path.join(src, item), os.path.join(dest_root, item)
        if os.path.isdir(s):
            shutil.copytree(s, d, dirs_exist_ok=True)
        else:
            shutil.copy2(s, d)
    shutil.rmtree(tmp, ignore_errors=True)


def _extract_server_zip(data, dest_root):
    """Extract ake_server.zip so the result is dest_root/ake_server/ containing
    adapter.py, api.py, etc. — a sibling of ake/ and AKE_MASTER.py, matching
    ake_server/adapter.py's own _ROOT expectation (one directory above ake_server/)."""
    tmp = _mkdtemp("ake_server_src_")
    with zipfile.ZipFile(io.BytesIO(data)) as z:
        z.extractall(tmp)
    src = tmp
    if not os.path.isfile(os.path.join(tmp, "adapter.py")):
        for name in os.listdir(tmp):
            sub = os.path.join(tmp, name)
            if os.path.isdir(sub) and os.path.isfile(os.path.join(sub, "adapter.py")):
                src = sub
                break
    dest = os.path.join(dest_root, "ake_server")
    if os.path.isdir(dest):
        shutil.rmtree(dest)
    shutil.copytree(src, dest)
    shutil.rmtree(tmp, ignore_errors=True)


def _mkdtemp(prefix):
    import tempfile
    return tempfile.mkdtemp(prefix=prefix)


def _place_workbook(root, workbook_bytes, workbook_name):
    """Copy an uploaded workbook beside AKE_MASTER.py so locate_workbook()'s own
    auto-discovery finds it (no new discovery logic invented here). Returns the absolute
    path used, or None to fall back to whatever AKE_Runtime.zip already bundled in root
    (the EBIS workbook)."""
    if not workbook_bytes:
        return None
    dest = os.path.join(root, workbook_name or "uploaded_workbook.xlsx")
    with open(dest, "wb") as f:
        f.write(workbook_bytes)
    return dest


