# Step 3 — write the fallback dashboard + gateway, install deps
# ============================================================================

def _write_embedded_assets(root):
    """Always write the bundled fallback dashboard + the gateway module. Whether the
    gateway actually SERVES this fallback, or reuses a frontend already shipped inside
    ake_server.zip instead, is decided inside ake_server_gateway.py itself at import
    time — this function doesn't need to know which one wins."""
    dash_dir = os.path.join(root, "ake_dashboard")
    os.makedirs(dash_dir, exist_ok=True)
    html = base64.b64decode(_DASHBOARD_HTML_B64).decode("utf-8")
    with open(os.path.join(dash_dir, "index.html"), "w", encoding="utf-8") as f:
        f.write(html)
    gw = base64.b64decode(_GATEWAY_PY_B64).decode("utf-8")
    with open(os.path.join(root, "ake_server_gateway.py"), "w", encoding="utf-8") as f:
        f.write(gw)


def _pip_install_quiet(root):
    reqs = []
    for rel in ("requirements.txt", os.path.join("ake_server", "requirements.txt")):
        p = os.path.join(root, rel)
        if os.path.isfile(p):
            reqs.append(p)
    if not reqs:
        return
    cmd = [sys.executable, "-m", "pip", "install", "-q"]
    for r in reqs:
        cmd += ["-r", r]
    print("Installing server dependencies…")
    res = subprocess.run(cmd, check=False, capture_output=True, text=True)
    if res.returncode != 0 and "externally-managed-environment" in (res.stderr or ""):
        # PEP 668 environments (some Debian/Ubuntu images) refuse a plain install. Colab
        # itself never hits this; the retry only exists so a local `python
        # AKE_Master_Launcher.py` behaves the same way there as it does in Colab.
        res = subprocess.run(cmd + ["--break-system-packages"], check=False,
                             capture_output=True, text=True)
    if res.returncode != 0:
        print("Dependency install reported an error — continuing anyway; if the server "
              "fails to start, the reason is most likely below:")
        print((res.stderr or res.stdout or "")[-800:])


# ============================================================================
# Step 4 — process lifecycle (safe to re-run this cell)
# ============================================================================

def _pidfile_path(root):
    return os.path.join(root, _PIDFILE_NAME)


def _kill_stale(root):
    """Best-effort: stop whatever THIS launcher started on a previous run of this cell,
    before wiping/recreating its working directory. Never touches anything it didn't
    itself start and record."""
    p = _pidfile_path(root)
    if not os.path.isfile(p):
        return
    try:
        with open(p) as f:
            pids = json.load(f)
    except Exception:
        return
    for pid in pids.values():
        try:
            os.kill(pid, signal.SIGTERM)
        except (ProcessLookupError, PermissionError):
            pass
    time.sleep(0.5)


def _save_pids(root, pids):
    with open(_pidfile_path(root), "w") as f:
        json.dump(pids, f)


def _start_server(root, env):
    log_path = os.path.join(root, "ake_server.log")
    log = open(log_path, "w")
    proc = subprocess.Popen(
        [sys.executable, "ake_server_gateway.py"],
        cwd=root, stdout=log, stderr=subprocess.STDOUT, env=env,
    )
    return proc, log_path


def _wait_for_health(port, timeout):
    import urllib.request
    url = "http://127.0.0.1:%d/health" % port
    deadline = time.time() + timeout
    while time.time() < deadline:
        try:
            with urllib.request.urlopen(url, timeout=2) as r:
                if r.status == 200:
                    return True
        except Exception:
            pass
        time.sleep(1)
    return False


def _ensure_cloudflared(root):
    exe = shutil.which("cloudflared")
    if exe:
        return exe
    local = os.path.join(root, "cloudflared")
    if os.path.isfile(local) and os.access(local, os.X_OK):
        return local
    print("Fetching cloudflared…")
    url = "https://github.com/cloudflare/cloudflared/releases/latest/download/cloudflared-linux-amd64"
    try:
        import urllib.request
        urllib.request.urlretrieve(url, local)
        os.chmod(local, 0o755)
        return local
    except Exception as e:
        print("Could not download cloudflared automatically (%s)." % e)
        print("Install it yourself and re-run, or run this in another cell first:")
        print("  !wget -q %s -O cloudflared && chmod +x cloudflared" % url)
        return None


def _start_tunnel(cloudflared_exe, port, root, timeout):
    log_path = os.path.join(root, "cloudflared.log")
    log = open(log_path, "w")
    proc = subprocess.Popen(
        [cloudflared_exe, "tunnel", "--url", "http://localhost:%d" % port,
         "--no-autoupdate", "--protocol", "http2"],
        stdout=log, stderr=subprocess.STDOUT,
    )
    url_re = re.compile(r"https://[a-zA-Z0-9-]+\.trycloudflare\.com")
    deadline = time.time() + timeout
    while time.time() < deadline:
        if proc.poll() is not None:
            break
        try:
            with open(log_path) as f:
                text = f.read()
            m = url_re.search(text)
            if m:
                return proc, m.group(0), log_path
        except FileNotFoundError:
            pass
        time.sleep(1)
    return proc, None, log_path


def _wait_for_tunnel_reachable(public_url, timeout):
    """A trycloudflare URL is printed by cloudflared the moment the tunnel REGISTERS, but
    Cloudflare's edge DNS for that random subdomain takes several seconds to propagate.
    Printing the URL immediately is why users hit DNS_PROBE_FINISHED_NXDOMAIN / "site can't
    be reached" — they open it before DNS exists. This polls the URL end-to-end (real DNS
    resolution + HTTP round-trip through the edge to the local server's /health) and only
    returns success once the URL actually serves. Returns (ok, detail)."""
    import urllib.request
    import urllib.error
    import socket
    health = public_url.rstrip("/") + "/health"
    deadline = time.time() + timeout
    last = "no response yet"
    attempt = 0
    while time.time() < deadline:
        attempt += 1
        try:
            req = urllib.request.Request(health, headers={"User-Agent": "ake-readiness"})
            with urllib.request.urlopen(req, timeout=8) as resp:
                if resp.status < 500:
                    return True, "reachable after %ds" % int(time.time() - (deadline - timeout))
                last = "HTTP %d" % resp.status
        except urllib.error.HTTPError as e:
            # Edge answered — DNS is live and the tunnel is up; the path just isn't 2xx.
            # That still means the URL is reachable, which is what we are verifying.
            return True, "edge responded (HTTP %d)" % e.code
        except (urllib.error.URLError, socket.gaierror, socket.timeout, ConnectionError) as e:
            reason = getattr(e, "reason", e)
            last = str(reason)
            # NXDOMAIN / name-resolution failures are the expected transient here.
        time.sleep(2 if attempt < 6 else 3)
    return False, last


def _start_tunnel_ready(cloudflared_exe, port, root, url_timeout, dns_timeout, attempts):
    """Bring up a tunnel AND confirm it is actually reachable before returning. If the
    tunnel registers but its DNS never resolves (a known quick-tunnel failure), or the
    process dies, tear it down and try again a few times with a fresh subdomain rather than
    handing back a dead URL. Returns (proc, url, log_path, ok, detail)."""
    last_detail = "not started"
    for attempt in range(1, attempts + 1):
        if attempt > 1:
            print("  Tunnel attempt %d/%d (previous: %s)…" % (attempt, attempts, last_detail))
        proc, url, log_path = _start_tunnel(cloudflared_exe, port, root, url_timeout)
        if not url:
            last_detail = "no URL within %ds" % url_timeout
            _terminate_quietly(proc)
            continue
        ok, detail = _wait_for_tunnel_reachable(url, dns_timeout)
        last_detail = detail
        if ok:
            return proc, url, log_path, True, detail
        # URL never became reachable — kill this tunnel and retry with a new subdomain.
        _terminate_quietly(proc)
    return None, None, os.path.join(root, "cloudflared.log"), False, last_detail


def _terminate_quietly(proc):
    if not proc:
        return
    try:
        proc.terminate()
        try:
            proc.wait(timeout=5)
        except Exception:
            proc.kill()
    except Exception:
        pass


def _tunnel_watchdog(port, root):
    """Quick tunnels drop — the process exits or the edge connection is lost, and the URL
    goes dead mid-session (another source of "site can't be reached"). This background
    thread notices when the cloudflared process has died and brings up a fresh, readiness-
    verified tunnel, updating the shared URL. It never touches a healthy tunnel. Runs until
    shutdown is requested."""
    while not _CONTROL["shutdown_requested"]:
        time.sleep(10)
        proc = _CONTROL.get("tunnel_proc")
        exe = _CONTROL.get("tunnel_exe")
        if proc is None or exe is None:
            continue
        if proc.poll() is None:
            continue  # tunnel process still alive — leave it alone
        # The tunnel died. Re-establish it with the same readiness guarantee.
        print("\n[tunnel] connection lost — reconnecting…")
        new_proc, new_url, _log, ok, detail = _start_tunnel_ready(
            exe, port, root, TUNNEL_TIMEOUT, TUNNEL_DNS_TIMEOUT, TUNNEL_ATTEMPTS
        )
        if new_proc is not None and new_url and ok:
            _CONTROL["tunnel_proc"] = new_proc
            _CONTROL["url"] = new_url
            _CONTROL["tunnel_reconnects"] += 1
            try:
                _save_pids(root, {"server": _CONTROL.get("server_pid"), "tunnel": new_proc.pid})
            except Exception:
                pass
            print("[tunnel] reconnected — new URL: %s" % new_url)
        else:
            print("[tunnel] reconnect failed (%s); will retry shortly." % detail)
            _CONTROL["tunnel_proc"] = None  # retry on the next watchdog tick


# ============================================================================
# Orchestration
# ============================================================================

_LAST_ROOT = None

# ============================================================================
# Owner control plane — this Colab process is the source of truth for mode/workbook
# ============================================================================
# The tunnel forwards every request from 127.0.0.1, so the server cannot tell the owner
# apart from a visitor by address. This token is what separates them. It is generated
# here, handed to the server through its environment, and never printed or served — the
# dashboard has no way to obtain it, so no visitor can change the runtime's mode.

_CONTROL = {
    "token": __import__("secrets").token_urlsafe(24),
    "mode": None,
    "port": None,
    "url": None,
    "feed_seq": 0,
    "watch": True,
    "last_activity": 0,       # epoch of last dashboard request (from feed)
    "last_event": None,       # the most recent feed entry (dict)
    "started_at": 0,          # epoch when the server started
    "idle_timeout": 30 * 60,  # seconds of no activity before graceful shutdown (default 30 min)
    "shutdown_requested": False,
    "tunnel_proc": None,      # the live cloudflared process (for the reconnect watchdog)
    "tunnel_exe": None,       # path to cloudflared, so the watchdog can respawn it
    "tunnel_reconnects": 0,   # how many times the watchdog has re-established the tunnel
    "server_pid": None,       # server process pid, so the watchdog can rewrite the pids file
}


def _ctl(path, payload=None, timeout=20):
    """One call to the gateway's control plane. Returns parsed JSON, or raises."""
    import urllib.request
    import urllib.error
    url = "http://127.0.0.1:%d%s" % (_CONTROL["port"] or SERVER_PORT, path)
    data = json.dumps(payload).encode() if payload is not None else None
    req = urllib.request.Request(url, data=data, headers={
        "x-ake-control-token": _CONTROL["token"],
        "Content-Type": "application/json",
    }, method="POST" if data is not None else "GET")
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return json.loads(r.read().decode("utf-8"))
    except urllib.error.HTTPError as e:
        body = e.read().decode("utf-8", "replace")
        try:
            body = json.loads(body).get("detail", body)
        except Exception:
            pass
        raise RuntimeError("%s: %s" % (e.code, body))


def _ask_mode():
    """Asked BEFORE the link exists, so no visitor ever meets a mode nobody chose.
    Changeable at any time afterwards with ':mode owner' / ':mode user'."""
    print()
    print("Which mode should this runtime start in?")
    print("  1. Owner  — everyone explores YOUR workbook (they cannot upload their own)")
    print("  2. User   — every visitor uploads their own workbook, private to them")
    while True:
        try:
            choice = input("Mode [1/2]: ").strip().lower()
        except (EOFError, KeyboardInterrupt):
            print("\nNo choice made — defaulting to Owner.")
            return "owner"
        if choice in ("1", "owner", "o", ""):
            return "owner"
        if choice in ("2", "user", "workspace", "u", "w"):
            return "workspace"
        print("Type 1 or 2.")


# ---------------------------------------------------------------- observer

def _drain_feed():
    """Pull latest dashboard activity. Updates _CONTROL state in place."""
    try:
        data = _ctl("/_ake/control/feed?since=%d&limit=5" % _CONTROL["feed_seq"], timeout=3)
    except Exception:
        return
    for e in data.get("entries", []):
        _CONTROL["feed_seq"] = max(_CONTROL["feed_seq"], e.get("seq", 0))
        _CONTROL["last_activity"] = max(_CONTROL["last_activity"], e.get("at", 0))
        _CONTROL["last_event"] = e  # keep only the latest


def _render_panel():
    """Build the control console status. No ANSI escape codes — Colab's output cell
    is HTML-based and renders them as garbage. Uses plain text with a separator."""
    _drain_feed()
    now = time.time()

    # Fetch server state with SHORT timeout — panel must never hang
    srv = None
    try:
        srv = _ctl("/_ake/control/state", timeout=3)
    except Exception:
        pass

    # Idle calculation
    last_act = _CONTROL["last_activity"] or _CONTROL["started_at"] or now
    idle_secs = int(now - last_act)
    idle_min, idle_sec = divmod(idle_secs, 60)
    remaining = max(0, _CONTROL["idle_timeout"] - idle_secs) if _CONTROL["idle_timeout"] > 0 else -1
    rem_str = "%02d:%02d" % divmod(int(remaining), 60) if remaining >= 0 else "disabled"

    # Last event
    ev = _CONTROL["last_event"]
    ev_ago = ""
    if ev and ev.get("at"):
        ago = int(now - ev["at"])
        ev_ago = "%ds ago" % ago if ago < 60 else "%dm ago" % (ago // 60)

    mode = (srv or {}).get("mode", _CONTROL.get("mode") or "?")
    wb = (srv or {}).get("workbook_name", "?")
    sessions = (srv or {}).get("active_sessions", "?")
    url = _CONTROL.get("url") or "—"

    lines = [
        "",
        "━" * 50,
        "  AKE Control Console",
        "━" * 50,
        "  Mode          : %s" % ("Owner" if mode == "owner" else "User"),
        "  Workbook      : %s" % wb,
        "  Dashboard     : %s" % ("ONLINE" if srv else "OFFLINE"),
        "  Sessions      : %s" % sessions,
        "─" * 50,
    ]
    if ev:
        lines += [
            "  Last Event    : %s" % ev_ago,
            "    Session     : %s" % (ev.get("session_id") or "—"),
            "    Action      : %s" % (ev.get("asked") or "—"),
            "    Entity      : %s" % (ev.get("entity") or "—"),
        ]
        if ev.get("workbook"):
            lines.append("    Workbook    : %s" % ev["workbook"])
    else:
        lines.append("  Last Event    : (none yet)")
    lines += [
        "─" * 50,
        "  Idle          : %02d:%02d" % (idle_min, idle_sec),
        "  Auto Shutdown : %s" % rem_str,
        "━" * 50,
    ]
    return "\n".join(lines)


def _check_idle_shutdown():
    """Check if idle timeout has elapsed. SHORT timeout on server call."""
    if _CONTROL["idle_timeout"] <= 0:
        return False
    now = time.time()
    last_act = _CONTROL["last_activity"] or _CONTROL["started_at"] or now
    if (now - last_act) < _CONTROL["idle_timeout"]:
        return False
    # Check active sessions before shutting down
    try:
        srv = _ctl("/_ake/control/state", timeout=3)
        if srv and srv.get("active_sessions", 0) > 0:
            return False
    except Exception:
        pass  # server unreachable = no sessions
    return True


# ---------------------------------------------------------------- control verbs

_CONTROL_HELP = """
Runtime control (this terminal only — visitors cannot reach these)
  :mode owner        everyone shares your workbook
  :mode user         every visitor uploads their own
  :workbook <path>   load a different workbook for NEW sessions
  :status            mode, workbook, live sessions
  :idle <minutes>    set auto-shutdown idle timeout (0 = disable)
  :shutdown          gracefully stop server + tunnel and exit
  :url               show the public dashboard URL again
  :help              this list
Press Enter on an empty line to refresh the control panel.
"""


def _handle_control(line):
    """Return True if this line was a launcher control verb and has been handled."""
    if not line.startswith(":"):
        return False
    parts = line[1:].strip().split(None, 1)
    verb = (parts[0] if parts else "").lower()
    arg = parts[1].strip() if len(parts) > 1 else ""

    try:
        if verb in ("help", "?"):
            print(_CONTROL_HELP)
        elif verb == "mode":
            if arg.lower() not in ("owner", "user", "workspace"):
                print("Usage: :mode owner | :mode user")
            else:
                r = _ctl("/_ake/control/mode", {"mode": arg.lower()})
                _CONTROL["mode"] = r["mode"]
                print("Mode is now: %s" % ("Owner" if r["mode"] == "owner" else "User"))
        elif verb == "workbook":
            if not arg:
                print("Usage: :workbook /content/my_registry.xlsx")
            else:
                r = _ctl("/_ake/control/workbook", {"path": os.path.abspath(os.path.expanduser(arg))})
                print("New sessions will use: %s" % r["workbook_name"])
        elif verb == "status":
            print(_render_panel())
        elif verb == "idle":
            if arg:
                try:
                    mins = int(arg)
                    _CONTROL["idle_timeout"] = max(0, mins * 60)
                    if mins == 0:
                        print("Auto-shutdown disabled.")
                    else:
                        print("Auto-shutdown set to %d minutes of idle." % mins)
                except ValueError:
                    print("Usage: :idle <minutes>  (0 to disable)")
            else:
                print("Current idle timeout: %d minutes" % (_CONTROL["idle_timeout"] // 60))
        elif verb == "shutdown":
            print("Shutting down server and tunnel...")
            _CONTROL["shutdown_requested"] = True
            return True
        elif verb == "url":
            print(_CONTROL["url"] or "No public URL was created.")
        elif verb == "watch":
            # Kept for backward compat but panel always shows latest
            if arg.lower() in ("on", "off"):
                _CONTROL["watch"] = (arg.lower() == "on")
        elif verb == "feed":
            # Legacy: drain and show the latest event
            _drain_feed()
            ev = _CONTROL["last_event"]
            if ev:
                print("  %s asked: %s → %s" % (ev.get("session_id","?"), ev.get("asked","?"), ev.get("entity","?")))
            else:
                print("  Nothing yet.")
        else:
            print("Unknown control verb ':%s'. Try :help" % verb)
    except Exception as e:
        print("Control call failed: %s" % e)
    return True


def stop_ake_server():
    """Convenience for this Colab session: stop the background dashboard server + tunnel
    this cell started. The interactive terminal below has nothing to stop — it only runs
    while this cell's input() loop is live, and exits on its own when you type 'exit'."""
    if not _LAST_ROOT:
        print("Nothing tracked to stop in this session.")
        return
    _kill_stale(_LAST_ROOT)
    print("Server and tunnel stopped (if they were running).")


def launch():
    global _LAST_ROOT
    root = WORKING_DIR or _default_working_dir()

    _kill_stale(root)  # stop anything a previous run of this cell left behind
    if os.path.isdir(root):
        shutil.rmtree(root, ignore_errors=True)
    os.makedirs(root, exist_ok=True)

    uploads = _collect_uploads()
    if not uploads:
        sys.exit("No files uploaded/found. Need AKE_Runtime.zip and ake_server.zip.")
    runtime_zip, server_zip, wb_bytes, wb_name = _classify_uploads(uploads)
    if not runtime_zip:
        sys.exit("Couldn't find AKE_Runtime.zip among the uploaded files.")
    if not server_zip:
        sys.exit("Couldn't find ake_server.zip among the uploaded files.")

    print("Extracting AKE Runtime…")
    _extract_runtime_zip(runtime_zip, root)
    print("Extracting ake_server…")
    _extract_server_zip(server_zip, root)

    explicit_wb = _place_workbook(root, wb_bytes, wb_name)
    if explicit_wb:
        print("Using uploaded workbook: %s" % os.path.basename(explicit_wb))
    else:
        print("No workbook uploaded — using the bundled EBIS workbook.")

    _write_embedded_assets(root)
    _pip_install_quiet(root)

    mode = SERVER_MODE or _ask_mode()
    if mode in ("user", "u"):
        mode = "workspace"
    _CONTROL["mode"] = mode

    env = os.environ.copy()
    env["AKE_SERVER_MODE"] = mode
    env["AKE_CONTROL_TOKEN"] = _CONTROL["token"]
    if explicit_wb:
        env["AKE_WORKBOOK"] = explicit_wb
    else:
        env.pop("AKE_WORKBOOK", None)
    env["AKE_SERVER_HOST"] = "0.0.0.0"
    env["AKE_SERVER_PORT"] = str(SERVER_PORT)

    print("Starting ake_server…")
    _CONTROL["port"] = SERVER_PORT
    server_proc, server_log = _start_server(root, env)
    pids = {"server": server_proc.pid}
    healthy = _wait_for_health(SERVER_PORT, STARTUP_TIMEOUT)

    if not healthy:
        tail = ""
        try:
            with open(server_log) as f:
                tail = f.read()[-1200:]
        except Exception:
            pass
        print("Warning: the server did not answer /health in time. Last log lines:\n" + tail)
        print("The interactive terminal below still works independently of the server.")
        _save_pids(root, pids)
    else:
        cloudflared_exe = _ensure_cloudflared(root)
        public_url = None
        tunnel_ready = False
        if cloudflared_exe:
            print("Starting the public tunnel…")
            tunnel_proc, public_url, tunnel_log, tunnel_ready, detail = _start_tunnel_ready(
                cloudflared_exe, SERVER_PORT, root, TUNNEL_TIMEOUT,
                TUNNEL_DNS_TIMEOUT, TUNNEL_ATTEMPTS
            )
            if tunnel_proc is not None:
                pids["tunnel"] = tunnel_proc.pid
            if public_url and tunnel_ready:
                print("  Tunnel is live and reachable (%s)." % detail)
                # Hand the live tunnel to the reconnect watchdog and start it once.
                _CONTROL["tunnel_proc"] = tunnel_proc
                _CONTROL["tunnel_exe"] = cloudflared_exe
                _CONTROL["server_pid"] = pids.get("server")
                _t = threading.Thread(target=_tunnel_watchdog, args=(SERVER_PORT, root), daemon=True)
                _t.start()
            elif public_url and not tunnel_ready:
                print(
                    "Warning: the tunnel registered a URL but its DNS did not resolve in "
                    "%ds (%s). The link may show DNS_PROBE_FINISHED_NXDOMAIN for a short "
                    "while — wait ~30s and reload, or re-run this cell for a fresh tunnel."
                    % (TUNNEL_DNS_TIMEOUT, detail)
                )
            else:
                print(
                    "Warning: could not bring up a reachable tunnel after %d attempts (%s). "
                    "Check %s — the server is still reachable locally on port %d inside "
                    "this runtime." % (TUNNEL_ATTEMPTS, detail, tunnel_log, SERVER_PORT)
                )
        _save_pids(root, pids)
        _CONTROL["url"] = public_url
        print()
        print("=" * 60)
        if public_url and tunnel_ready:
            print("  AKE Dashboard:  %s" % public_url)
        elif public_url:
            print("  AKE Dashboard:  %s   (DNS still propagating — see warning)" % public_url)
        else:
            print("  AKE Dashboard: tunnel URL unavailable — see warning above")
        print("  Mode:           %s" % ("Owner" if _CONTROL["mode"] == "owner" else "User"))
        print("=" * 60)
        print()
        print("Copy that URL and share it with your users. It's only shown here — "
              "nowhere in the dashboard or the API exposes it.")
        print("Change mode or workbook any time below with :mode / :workbook — type "
              ":help for the full list.")
        print()

    _LAST_ROOT = root
    return root, explicit_wb


def main():
    root, wb_arg = launch()
    _CONTROL["started_at"] = time.time()
    _CONTROL["last_activity"] = time.time()

    sys.path.insert(0, root)

    # Show initial status
    print(_render_panel())
    if _CONTROL.get("url"):
        print("  Dashboard URL: %s" % _CONTROL["url"])
    print("\n  Type :help for controls. Press Enter to refresh status.\n")

    # Control console loop
    while True:
        try:
            line = input("AKE> ").strip()
        except (EOFError, KeyboardInterrupt):
            print("\nExiting...")
            break

        # Empty line = refresh panel + idle check
        if not line:
            if _check_idle_shutdown():
                print("\n  Idle timeout reached. Shutting down gracefully...")
                break
            print(_render_panel())
            continue

        # Control verbs
        if line.startswith(":"):
            _handle_control(line)
            if _CONTROL["shutdown_requested"]:
                break
            # Show panel after control verb (unless it was :help which prints its own output)
            continue

        # Any non-control input — alias common bare words before rejecting
        _BARE_ALIASES = {"help": ":help", "stop": ":shutdown", "exit": ":shutdown",
                         "quit": ":shutdown", "status": ":status", "url": ":url"}
        if line in _BARE_ALIASES:
            _handle_control(_BARE_ALIASES[line])
            if _CONTROL["shutdown_requested"]:
                break
            continue
        print("  Unknown command '%s'. Type :help for controls." % line)

    # Graceful shutdown
    _kill_stale(root)
    print("\n  Server and tunnel stopped.")
    print("  Dashboard URL is no longer active.")
    print("  Run stop_ake_server() from another cell, or re-run this cell to restart.")


if __name__ == "__main__":
    main()
